-- C2 article persistence: create, save, provenance, guards and grants.
-- Part of the local PostgreSQL test harness; run only through supabase/tests/run.sh,
-- which creates and destroys its own disposable cluster. Never run against a hosted database.


\set ON_ERROR_STOP 1
create schema if not exists test_util;
grant usage on schema test_util to service_role, anon, authenticated;
create or replace function test_util.expect(p_label text, p_got jsonb, p_outcome text, p_extra text default null) returns void language plpgsql as $$
begin
  if p_got ->> 'outcome' is distinct from p_outcome or (p_extra is not null and p_got ->> 'reason' is distinct from p_extra) then
    raise exception 'FAIL %: expected % %, got %', p_label, p_outcome, coalesce(p_extra,''), p_got;
  end if;
  raise notice 'PASS %', p_label;
end $$;
create or replace function test_util.expect_error(p_label text, p_sql text, p_state text) returns void language plpgsql as $$
begin
  begin
    execute p_sql;
  exception when others then
    if sqlstate = p_state then raise notice 'PASS % (refused %)', p_label, sqlstate; return; end if;
    raise exception 'FAIL %: expected sqlstate %, got % %', p_label, p_state, sqlstate, sqlerrm;
  end;
  raise exception 'FAIL %: statement was not refused', p_label;
end $$;
grant execute on function test_util.expect(text,jsonb,text,text) to service_role, anon, authenticated;
grant execute on function test_util.expect_error(text,text,text) to service_role, anon, authenticated;

set role service_role;
