-- grants: service_role reads, never writes directly
select test_util.expect_error('service_role cannot insert a version', 'insert into nexra_article_versions (article_id, version, origin, canonical_content, content_sha256, created_by) select id, 9, ''operator'', ''x'', ''x'', created_by from nexra_articles limit 1', '42501');
select test_util.expect_error('service_role cannot update a parent', 'update nexra_articles set status = ''approved''', '42501');
select test_util.expect_error('service_role cannot delete sources', 'delete from nexra_article_version_sources', '42501');
select test_util.expect_error('service_role cannot call internal helpers', 'select nexra_article_check_sources(''halcyon-fintech'', ''[]''::jsonb)', '42501');
reset role;
set role anon;
select test_util.expect_error('anon cannot read articles', 'select * from nexra_articles', '42501');
select test_util.expect_error('anon cannot read versions', 'select * from nexra_article_versions', '42501');
select test_util.expect_error('anon cannot create', 'select nexra_article_create(''a'',gen_random_uuid(),''x'',''x'',''[]''::jsonb,gen_random_uuid())', '42501');
reset role;
set role authenticated;
select test_util.expect_error('authenticated cannot read sources', 'select * from nexra_article_version_sources', '42501');
select test_util.expect_error('authenticated cannot save', 'select nexra_article_save_version(''a'',gen_random_uuid(),1::smallint,''x'',''x'',''[]''::jsonb,gen_random_uuid())', '42501');
reset role;

