-- no side effects on drafts, fact-checks, approvals or proposals
do $$ begin
  if exists (select 1 from nexra_content_draft_versions where fact_check is not null) then raise exception 'FAIL fact_check written'; end if;
  if exists (select 1 from nexra_content_drafts where status <> 'drafting' or approved_version is not null) then raise exception 'FAIL draft changed'; end if;
  if exists (select 1 from nexra_content_publication_proposals) then raise exception 'FAIL proposal written'; end if;
  raise notice 'PASS no draft, fact-check, approval or proposal side effects';
end $$;
